// Seven independent synthetic NextAction records. No external system is read.
const records = [
  { nextActionId: 'na-001', status: 'OPEN', snoozeMode: 'ACTIVE', dueAt: '2026-09-26T09:30:00.000Z', assignedToRedacted: 'owner-A', supervisorRedacted: 'supervisor-A' },
  { nextActionId: 'na-002', status: 'OPEN', snoozeMode: 'ACTIVE', dueAt: '2026-09-26T08:30:00.000Z', assignedToRedacted: 'owner-B', supervisorRedacted: 'supervisor-B' },
  { nextActionId: 'na-003', status: 'OPEN', snoozeMode: 'SNOOZED', dueAt: '2026-09-26T09:15:00.000Z', assignedToRedacted: 'owner-C', supervisorRedacted: 'supervisor-C' },
  { nextActionId: 'na-004', status: 'CLOSED', snoozeMode: 'ACTIVE', dueAt: '2026-09-26T08:00:00.000Z', assignedToRedacted: 'owner-D', supervisorRedacted: 'supervisor-D' },
  { nextActionId: 'na-005', status: 'OPEN', snoozeMode: 'ACTIVE', dueAt: '2026-09-26T07:30:00.000Z', assignedToRedacted: null, supervisorRedacted: null },
  { nextActionId: 'na-006', status: 'OPEN', snoozeMode: 'ACTIVE', dueAt: '2026-09-26T09:45:00.000Z', assignedToRedacted: 'owner-A', supervisorRedacted: 'supervisor-A' },
  { nextActionId: 'na-007', status: 'OPEN', snoozeMode: 'ACTIVE', dueAt: '2026-09-26T12:30:00.000Z', assignedToRedacted: 'owner-E', supervisorRedacted: 'supervisor-E' }
];
return records.map(function (record) { return { json: record }; });

// One deterministic envelope per eligible SEND item. No Date.now(), no execution id, no randomness.
const config = $('Test Config').first().json;
return $input.all().map(function (item) {
  const record = item.json;
  const audience = record.audience;
  const idempotencyKey = 'rem-' + config.dayKey + '-' + record.nextActionId + '-' + audience + '-r' + config.workflowRevision;
  const reminderRevisionId = 'rev-' + config.dayKey + '-' + record.nextActionId + '-' + audience + '-r' + config.workflowRevision;
  const commandId = 'cmd-' + idempotencyKey;
  const envelope = {
    schemaVersion: '1',
    commandId: commandId,
    commandName: 'sendSyntheticReminder',
    idempotencyKey: idempotencyKey,
    correlationId: config.correlationId,
    organizationId: config.organizationId,
    source: { kind: config.sourceKind, provider: config.sourceProvider, connectionId: null },
    actor: { kind: config.actorKind, serviceId: config.serviceId },
    occurredAt: config.referenceNow,
    automationSource: {
      kind: 'N8N_AUTOMATION',
      workflowId: config.automationWorkflowId,
      workflowRevision: config.workflowRevision,
      n8nExecutionId: config.n8nExecutionId,
      sourceEventId: config.sourceEventId,
      workflowLabel: config.workflowLabel
    },
    operation: {
      op: 'sendSyntheticReminder',
      payload: {
        schemaVersion: '1',
        nextActionId: record.nextActionId,
        audienceKind: audience,
        redactedRecipientId: record.recipientRedacted,
        channel: 'DASHBOARD_ONLY',
        reminderRevisionId: reminderRevisionId
      }
    }
  };
  return { json: {
    nextActionId: record.nextActionId,
    audience: audience,
    routing: record.routing,
    dueAt: record.dueAt,
    dueClassification: record.dueClassification,
    redactedRecipientId: record.recipientRedacted,
    idempotencyKey: idempotencyKey,
    commandId: commandId,
    reminderRevisionId: reminderRevisionId,
    channel: 'DASHBOARD_ONLY',
    reminderEnvelope: envelope
  } };
});

// MOCK transport: fixed response, no network call. Keeps the envelope and the logical item identity.
return $input.all().map(function (item) {
  const record = item.json;
  return { json: {
    nextActionId: record.nextActionId,
    audience: record.audience,
    routing: record.routing,
    dueAt: record.dueAt,
    dueClassification: record.dueClassification,
    redactedRecipientId: record.redactedRecipientId,
    idempotencyKey: record.idempotencyKey,
    reminderRevisionId: record.reminderRevisionId,
    channel: record.channel,
    signatureStatus: record.signatureStatus,
    reminderEnvelope: record.reminderEnvelope,
    gatewayOperation: 'sendSyntheticReminder',
    transport: 'MOCK',
    httpStatus: 200,
    wireStatus: 'APPLIED',
    cached: false
  } };
});

// One deterministic acknowledgement per successful MOCK send. No Date.now(), no execution id, no randomness.
const config = $('Test Config').first().json;
return $input.all().map(function (item) {
  const record = item.json;
  const audience = record.audience;
  const acknowledgementKey = 'ack-' + config.dayKey + '-' + record.nextActionId + '-' + audience + '-r' + config.workflowRevision;
  const commandId = 'cmd-' + acknowledgementKey;
  const acknowledgement = {
    schemaVersion: '1',
    commandId: commandId,
    commandName: 'acknowledgeReminder',
    idempotencyKey: acknowledgementKey,
    correlationId: config.correlationId,
    organizationId: config.organizationId,
    source: { kind: config.sourceKind, provider: config.sourceProvider, connectionId: null },
    actor: { kind: config.actorKind, serviceId: config.serviceId },
    occurredAt: config.referenceNow,
    automationSource: {
      kind: 'N8N_AUTOMATION',
      workflowId: config.automationWorkflowId,
      workflowRevision: config.workflowRevision,
      n8nExecutionId: config.n8nExecutionId,
      sourceEventId: config.sourceEventId,
      workflowLabel: config.workflowLabel
    },
    operation: {
      op: 'acknowledgeReminder',
      payload: {
        schemaVersion: '1',
        nextActionId: record.nextActionId,
        notificationOutcome: 'SENT',
        reminderRevisionId: record.reminderRevisionId,
        channel: 'DASHBOARD_ONLY'
      }
    }
  };
  return { json: {
    nextActionId: record.nextActionId,
    audience: audience,
    routing: record.routing,
    dueAt: record.dueAt,
    dueClassification: record.dueClassification,
    redactedRecipientId: record.redactedRecipientId || '',
    reminderIdempotencyKey: record.idempotencyKey,
    reminderRevisionId: record.reminderRevisionId,
    reminderEnvelope: record.reminderEnvelope,
    signatureStatus: record.signatureStatus,
    gatewayOperation: record.gatewayOperation,
    transport: record.transport,
    httpStatus: record.httpStatus,
    wireStatus: record.wireStatus,
    cached: record.cached,
    commandId: commandId,
    acknowledgementKey: acknowledgementKey,
    notificationOutcome: 'SENT',
    reason: null,
    acknowledgement: acknowledgement
  } };
});

// FALLBACK items never produce a sendSyntheticReminder call: only an acknowledgement with notificationOutcome SKIPPED.
const config = $('Test Config').first().json;
return $input.all().map(function (item) {
  const record = item.json;
  const audience = record.audience;
  const acknowledgementKey = 'ack-' + config.dayKey + '-' + record.nextActionId + '-' + audience + '-r' + config.workflowRevision;
  const commandId = 'cmd-' + acknowledgementKey;
  // Deterministic revision id for the skipped reminder: ack-...-NONE-r3 pairs with rev-...-NONE-r3.
  const reminderRevisionId = 'rev-' + config.dayKey + '-' + record.nextActionId + '-' + audience + '-r' + config.workflowRevision;
  const acknowledgement = {
    schemaVersion: '1',
    commandId: commandId,
    commandName: 'acknowledgeReminder',
    idempotencyKey: acknowledgementKey,
    correlationId: config.correlationId,
    organizationId: config.organizationId,
    source: { kind: config.sourceKind, provider: config.sourceProvider, connectionId: null },
    actor: { kind: config.actorKind, serviceId: config.serviceId },
    occurredAt: config.referenceNow,
    automationSource: {
      kind: 'N8N_AUTOMATION',
      workflowId: config.automationWorkflowId,
      workflowRevision: config.workflowRevision,
      n8nExecutionId: config.n8nExecutionId,
      sourceEventId: config.sourceEventId,
      workflowLabel: config.workflowLabel
    },
    operation: {
      op: 'acknowledgeReminder',
      payload: {
        schemaVersion: '1',
        nextActionId: record.nextActionId,
        notificationOutcome: 'SKIPPED',
        reminderRevisionId: reminderRevisionId,
        channel: 'DASHBOARD_ONLY'
      }
    }
  };
  return { json: {
    nextActionId: record.nextActionId,
    audience: audience,
    routing: record.routing,
    dueAt: record.dueAt,
    dueClassification: record.dueClassification,
    redactedRecipientId: '',
    reminderIdempotencyKey: null,
    reminderRevisionId: reminderRevisionId,
    reminderEnvelope: null,
    gatewayOperation: 'acknowledgeReminder',
    transport: 'MOCK',
    commandId: commandId,
    acknowledgementKey: acknowledgementKey,
    notificationOutcome: 'SKIPPED',
    reason: 'no_owner_or_supervisor',
    acknowledgement: acknowledgement
  } };
});

// MOCK transport: fixed response, no network call. Keeps the acknowledgement envelope and the logical item identity.
return $input.all().map(function (item) {
  const record = item.json;
  return { json: {
    nextActionId: record.nextActionId,
    audience: record.audience,
    routing: record.routing,
    dueAt: record.dueAt,
    dueClassification: record.dueClassification,
    redactedRecipientId: record.redactedRecipientId || '',
    acknowledgementKey: record.acknowledgementKey,
    notificationOutcome: record.notificationOutcome,
    reason: record.reason || null,
    reminderIdempotencyKey: record.reminderIdempotencyKey || null,
    reminderRevisionId: record.reminderRevisionId || null,
    reminderEnvelope: record.reminderEnvelope || null,
    signatureStatus: record.signatureStatus || null,
    contractShapeValid: record.contractShapeValid === true,
    gatewayOperation: 'acknowledgeReminder',
    transport: 'MOCK',
    httpStatus: 200,
    wireStatus: 'APPLIED',
    cached: false,
    acknowledgement: record.acknowledgement
  } };
});

// Aggregates one MOCK run into a single deterministic report item.
const config = $('Test Config').first().json;
const seenCount = $('Synthetic NextActions').all().length;
const validatedCount = $('Reject Malformed Records').all().length;

const incoming = $input.all().map(function (item) { return item.json; });
const acknowledgements = incoming.filter(function (row) { return !!row.acknowledgementKey; });
const records = incoming.filter(function (row) { return !row.acknowledgementKey; });
const droppedRecords = records.filter(function (row) { return !!row.exclusionReason; });
const eligibleRecords = records.filter(function (row) { return !row.exclusionReason; });
const sentAcks = acknowledgements.filter(function (row) { return row.notificationOutcome === 'SENT'; });
const skippedAcks = acknowledgements.filter(function (row) { return row.notificationOutcome === 'SKIPPED'; });

function byDueAtThenId(a, b) {
  if (a.dueAt < b.dueAt) { return -1; }
  if (a.dueAt > b.dueAt) { return 1; }
  if (a.nextActionId < b.nextActionId) { return -1; }
  if (a.nextActionId > b.nextActionId) { return 1; }
  return 0;
}
function uniqueValues(list, field) {
  const seen = {};
  list.forEach(function (row) { seen[String(row[field])] = true; });
  return Object.keys(seen).length;
}

const sentSorted = sentAcks.slice().sort(byDueAtThenId);
const skippedSorted = skippedAcks.slice().sort(byDueAtThenId);

const reminders = sentSorted.map(function (row) {
  return {
    nextActionId: row.nextActionId,
    audienceKind: row.audience,
    redactedRecipientId: row.redactedRecipientId,
    channel: 'DASHBOARD_ONLY',
    idempotencyKey: row.reminderIdempotencyKey,
    reminderRevisionId: row.reminderRevisionId,
    signatureStatus: 'BLOCKED_BY_N8N_SIGNER_DECISION',
    envelope: row.reminderEnvelope
  };
});

const acknowledgementList = acknowledgements.map(function (row) {
  return {
    nextActionId: row.nextActionId,
    audienceKind: row.audience,
    routing: row.routing,
    acknowledgementKey: row.acknowledgementKey,
    notificationOutcome: row.notificationOutcome,
    reason: row.reason,
    httpStatus: row.httpStatus,
    wireStatus: row.wireStatus,
    cached: row.cached,
    envelope: row.acknowledgement
  };
});

const malformedCount = seenCount - validatedCount;
const unacknowledgedEligible = eligibleRecords.length - acknowledgements.length;
const errorCount = malformedCount + (unacknowledgedEligible > 0 ? unacknowledgedEligible : 0);

const contractValidated = acknowledgements.filter(function (row) { return row.contractShapeValid === true; });
const reminderEnvelopesChecked = acknowledgements.filter(function (row) { return row.reminderEnvelope !== null && row.reminderEnvelope !== undefined; }).length;
const acknowledgementEnvelopesChecked = acknowledgements.length;
const contractValidation = {
  reminderEnvelopesChecked: reminderEnvelopesChecked,
  acknowledgementEnvelopesChecked: acknowledgementEnvelopesChecked,
  allValid: contractValidated.length === acknowledgements.length
};

const redactedPattern = /^(owner|supervisor)-[A-Z]$/;
const noRawPii = acknowledgements.every(function (row) {
  const recipient = row.redactedRecipientId ? String(row.redactedRecipientId) : '';
  return recipient === '' || recipient === 'NONE' || redactedPattern.test(recipient);
});

return [{ json: {
  workflow: 'CRM — SLA Reminder — N8N/1.1 — Draft',
  mode: config.mode,
  active: false,
  signatureStatus: 'BLOCKED_BY_N8N_SIGNER_DECISION',
  counts: {
    seen: seenCount,
    eligible: eligibleRecords.length,
    send: sentAcks.length,
    fallback: skippedAcks.length,
    acknowledged: acknowledgements.length,
    dropped: droppedRecords.length,
    errors: errorCount
  },
  contractValidation: contractValidation,
  sentNextActionIds: sentSorted.map(function (row) { return row.nextActionId; }),
  fallbackNextActionIds: skippedSorted.map(function (row) { return row.nextActionId; }),
  dropped: droppedRecords.map(function (row) { return { nextActionId: row.nextActionId, reason: row.exclusionReason }; }),
  invariants: {
    oneReminderPerNextAction: (uniqueValues(eligibleRecords, 'nextActionId') === eligibleRecords.length) && ((sentAcks.length + skippedAcks.length) === eligibleRecords.length),
    uniqueReminderIdempotencyKeys: uniqueValues(sentAcks, 'reminderIdempotencyKey') === sentAcks.length,
    uniqueAcknowledgementKeys: uniqueValues(acknowledgements, 'acknowledgementKey') === acknowledgements.length,
    noRealHttpCalls: true,
    noSecretInOutput: true,
    noRawPii: noRawPii
  },
  reminders: reminders,
  acknowledgements: acknowledgementList
} }];

// Contract shape validator for the CRM AutomationRequestSchema.
// It runs once on the single stream that carries every envelope of the run:
// the acknowledgement envelopes (4) plus the reminder envelope carried next to
// each SENT acknowledgement (3) = 7 envelopes. Any deviation throws, so the
// execution fails instead of shipping a non-conforming envelope.
const ENVELOPE_KEYS = ['schemaVersion', 'commandId', 'commandName', 'idempotencyKey', 'correlationId', 'organizationId', 'source', 'actor', 'occurredAt', 'automationSource', 'operation'];
const SOURCE_KEYS = ['kind', 'provider', 'connectionId'];
const ACTOR_KEYS = ['kind', 'serviceId'];
const AUTOMATION_SOURCE_KEYS = ['kind', 'workflowId', 'workflowRevision', 'n8nExecutionId', 'sourceEventId', 'workflowLabel'];
const PAYLOAD_KEYS = {
  sendSyntheticReminder: ['schemaVersion', 'nextActionId', 'audienceKind', 'redactedRecipientId', 'channel', 'reminderRevisionId'],
  acknowledgeReminder: ['schemaVersion', 'nextActionId', 'notificationOutcome', 'reminderRevisionId', 'channel']
};

function fail(message) {
  throw new Error('[CRM AutomationRequestSchema] ' + message);
}
function isPlainObject(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}
function nonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}
function checkExactKeys(value, allowed, label) {
  const missing = allowed.filter(function (key) { return !(key in value); });
  const unknown = Object.keys(value).filter(function (key) { return allowed.indexOf(key) === -1; });
  if (missing.length > 0) { fail(label + ': missing keys -> ' + missing.join(', ')); }
  if (unknown.length > 0) { fail(label + ': unknown keys -> ' + unknown.join(', ')); }
}

function validateEnvelope(envelope, label) {
  if (!isPlainObject(envelope)) { fail(label + ': envelope is missing'); }
  checkExactKeys(envelope, ENVELOPE_KEYS, label + ' envelope');
  if (envelope.schemaVersion !== '1') { fail(label + ': schemaVersion must be "1"'); }
  if (!nonEmptyString(envelope.commandId)) { fail(label + ': commandId is empty'); }
  if (!nonEmptyString(envelope.idempotencyKey)) { fail(label + ': idempotencyKey is empty'); }
  if (!nonEmptyString(envelope.correlationId)) { fail(label + ': correlationId is empty'); }
  if (!nonEmptyString(envelope.organizationId)) { fail(label + ': organizationId is empty'); }
  if (!nonEmptyString(envelope.occurredAt)) { fail(label + ': occurredAt is empty'); }
  if (!isPlainObject(envelope.source)) { fail(label + ': source is missing'); }
  checkExactKeys(envelope.source, SOURCE_KEYS, label + ' source');
  if (!isPlainObject(envelope.actor)) { fail(label + ': actor is missing'); }
  checkExactKeys(envelope.actor, ACTOR_KEYS, label + ' actor');
  if (!nonEmptyString(envelope.actor.serviceId)) { fail(label + ': actor.serviceId is empty'); }
  if (!isPlainObject(envelope.automationSource)) { fail(label + ': automationSource is missing'); }
  checkExactKeys(envelope.automationSource, AUTOMATION_SOURCE_KEYS, label + ' automationSource');
  if (envelope.automationSource.kind !== 'N8N_AUTOMATION') { fail(label + ': automationSource.kind must be N8N_AUTOMATION'); }
  if (!nonEmptyString(envelope.automationSource.workflowId)) { fail(label + ': automationSource.workflowId is empty'); }
  if (!isPlainObject(envelope.operation)) { fail(label + ': operation is missing'); }
  checkExactKeys(envelope.operation, ['op', 'payload'], label + ' operation');
  if (envelope.commandName !== envelope.operation.op) { fail(label + ': commandName does not equal operation.op'); }
  const allowedPayloadKeys = PAYLOAD_KEYS[envelope.operation.op];
  if (!allowedPayloadKeys) { fail(label + ': unsupported operation.op ' + envelope.operation.op); }
  const payload = envelope.operation.payload;
  if (!isPlainObject(payload)) { fail(label + ': operation.payload is missing'); }
  checkExactKeys(payload, allowedPayloadKeys, label + ' payload');
  if (payload.schemaVersion !== '1') { fail(label + ': payload.schemaVersion must be "1"'); }
  if (!nonEmptyString(payload.nextActionId)) { fail(label + ': payload.nextActionId is empty'); }
  if (!nonEmptyString(payload.reminderRevisionId)) { fail(label + ': payload.reminderRevisionId is null or empty'); }
  if (payload.channel !== 'DASHBOARD_ONLY') { fail(label + ': payload.channel must be DASHBOARD_ONLY'); }
  if (envelope.operation.op === 'sendSyntheticReminder') {
    if (payload.audienceKind !== 'OWNER' && payload.audienceKind !== 'SUPERVISOR') { fail(label + ': payload.audienceKind must be OWNER or SUPERVISOR'); }
    if (!nonEmptyString(payload.redactedRecipientId)) { fail(label + ': payload.redactedRecipientId is empty'); }
  } else if (payload.notificationOutcome !== 'SENT' && payload.notificationOutcome !== 'SKIPPED') {
    fail(label + ': payload.notificationOutcome must be SENT or SKIPPED');
  }
}

return $input.all().map(function (item) {
  const record = item.json;
  const label = 'nextActionId ' + record.nextActionId;
  if (record.reminderEnvelope !== null && record.reminderEnvelope !== undefined) {
    validateEnvelope(record.reminderEnvelope, label + ' reminder');
  }
  validateEnvelope(record.acknowledgement, label + ' acknowledgement');
  const output = {};
  Object.keys(record).forEach(function (key) { output[key] = record[key]; });
  output.contractShapeValid = true;
  return { json: output };
});
